#!/usr/bin/env node
/**
 * Custom block deployment CLI invoked by Notion's worker build sandbox.
 *
 * It ships with the SDK so worker projects expose the executable expected by
 * the deployment pipeline at `node_modules/.bin/notion-custom-blocks`.
 */
import { buildCustomBlocks, printBuildOutput } from "./build.js";
import { parseUploadsInput, uploadViews } from "./upload.js";
export async function main(argv) {
    const [command, ...rest] = argv;
    switch (command) {
        case "build":
            return runBuild(rest);
        case "upload":
            return runUpload(rest);
        default:
            printUsage();
            return command === undefined ? 0 : 1;
    }
}
async function runBuild(args) {
    const flags = parseFlags(args);
    const out = flags.out;
    if (out === undefined) {
        process.stderr.write("usage: notion-custom-blocks build --out <dir>\n");
        return 1;
    }
    const { manifest, cwd } = flags;
    const output = await buildCustomBlocks({ out, manifest, cwd });
    printBuildOutput(output);
    return 0;
}
async function runUpload(args) {
    const flags = parseFlags(args);
    const raw = flags.uploads;
    if (raw === undefined) {
        process.stderr.write("usage: notion-custom-blocks upload --uploads '<json>'\n");
        return 1;
    }
    const uploads = parseUploadsInput(raw);
    const output = await uploadViews(uploads);
    process.stdout.write(`${JSON.stringify(output)}\n`);
    return 0;
}
function parseFlags(args) {
    const flags = {};
    for (let i = 0; i < args.length; i++) {
        const arg = args[i];
        if (arg === undefined || !arg.startsWith("--")) {
            continue;
        }
        const name = arg.slice(2);
        const value = args[i + 1];
        if (value === undefined) {
            continue;
        }
        flags[name] = value;
        i++;
    }
    return flags;
}
function printUsage() {
    process.stderr.write("Invalid command. See notion-custom-blocks source.");
}
main(process.argv.slice(2))
    .then(code => {
    process.exitCode = code;
})
    .catch((error) => {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 1;
});
